
cc.Class({
    extends: require('LMSlots_GameData_Base'),

    properties: {
        _needBonusNum:6,                    //触发bonus游戏需求的金币数
        _isCollectGame:false,               //是否是收集游戏
    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){
        this._super(deskInfo,gameId,gameJackpot);
        this._bonusData = this._deskInfo.bonusData;
        this._selectData = this._deskInfo.select;
        this._poolList = this._bonusData.poolList;
     },
    //重写接收服务器消息
    OnRcvNetSpine:function(msg){
        //msg = {"c":44,"code":200,"spLuXian":0,"betcoin":90000,"wincoin":0,"freeResult":{"freeInfo":[],"triFreeCnt":0},"subGameInfo":{"subGamid":-1,"isMustJoin":-1},"lastBetCoin":9998845000,"addMult":1,"allFreeCnt":0,"coin":9998845000,"nextBetLine":{"spcode":500},"freeCnt":0,"spcode":200,"bonusData":{"num":0,"data":{"idx_6":{"idx":6,"pool":0,"coin":450000},"idx_11":{"idx":11,"pool":0,"coin":45000},"idx_7":{"idx":7,"pool":0,"coin":45000},"idx_3":{"idx":3,"pool":2,"coin":0},"idx_14":{"idx":14,"pool":0,"coin":360000}},"coin":0},"spEffect":{"wincoin":0,"kind":0},"pooljp":0,"scatterZJLuXian":[],"select":{"state":true,"rtype":1},"mults":[10000,20000,30000,40000,50000,60000,70000,80000,90000],"freeWinCoin":0,"zjLuXian":[],"resultCards":[7,3,8,1,7,8,8,2,1,2,8,3,1,8]}
        if(msg.code == 200){
            this._bonusData = msg.bonusData;
            this._selectData = msg.select;
            if(this._bonusData){
                this._poolList = this._bonusData.poolList;
            }
            this._super(msg);
        }
    },

    //获取奖池数 type 1mini
    getPoolbyType(type){
        if(this._poolList)
            return this._poolList[type-1];
        return 0;
    },

    //获取bonusdata
    GetBounusData(){
        return this._bonusData;
    },
    
    //清除bonus状态
    clearBonusState(){
        this._bonusData.state = false;
    },

    //获取select
    GetSelectData(){
        return this._selectData;
    },

    //清除select状态
    clearSelectState(){
        this._selectData.state = false;
    },

    //设置top/bottom的脚本
    SetGameScript:function(fgame){
        this._freeGame = fgame
    },

    GetFreeGameScript:function(){
        return this._freeGame
    },

    //设置是否是收集游戏
    SetCollectGame:function(isCollectGame){
        this._isCollectGame = isCollectGame
    },

    GetCollectGame:function(){
        return this._isCollectGame
    },

    //是否免费游戏中
    isFreeGame(){
        return this._bonusData.state;
    },

    //进入bonus游戏需求的bonus icon数
    getNeedBonusIconNum(){
        return this._needBonusNum;
    },

    setBonusIconNum(num){
        this._needBonusNum = num;
    },

    //清除当前索引的pool值(已经领取了)
    clearBonusDataPool(index){
        let bonusdata = this._bonusData.data;
        for(let key in bonusdata){
            if(bonusdata[key].idx == index){
                bonusdata[key].pool = 0;
                break;
            }
        }
    },

    //按节点播放spine
    playSpine:function(node,aniName,loop,endCall){
        if(node){
            node.active = true
            let ske = node.getComponent(sp.Skeleton)
            if(ske){
                ske.setAnimation(0,aniName,loop)
                ske.setCompleteListener(() => {
                    if(endCall){
                        endCall()
                    }
                })
            }
        }
        
    },
});
