

cc.Class({
    extends: require('LMSlots_Symbol_Base'),

    properties: {
       totalCoin:0,
       pool:0,
       showtype:0,          //1代表数值 2代表jackpot
    },

    onLoad(){
        this._num = cc.find('num',this.node);
        this._jackpot = cc.find('getjackpot',this.node);
        this._bottom = cc.find('bottombg',this.node);
        this._top = cc.find('topbag',this.node);
        this._kuangguang = cc.find('kuang_guang',this.node);
        this._kuang = cc.find('kuang',this.node);
        this._numscalesp = cc.find('numscalesp',this.node);
        this._nummovebtsp = cc.find('nummovebtsp',this.node);

        this._freeSymbolName = cc.vv.gameData.getGameCfg().shadowSymbolNode;
    },

    //断线重连初始化显示符号 selectstate true表示需要操作
    initShowSymbol(id,pool,coin,selectstate){
        this._id = id;
        this._pool = pool;
        this._showNode = cc.find(this._freeSymbolName,this.node)
        this.playSymbolAni(1);
        if(pool||coin){
            this._kuang.active = true;
        }
        
        //下面显示coin
        if(pool){
            this.resetFrameColor(this._top);
            let jackimg = cc.find('jackpotimg',this._top);
            this.updateJackpotImg(jackimg,'base','theme132_s_top'+(28+pool));
        }
        if(coin){
            this.resetFrameColor(this._bottom);
            cc.find('totalnum',this._bottom).getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,0);
        }
    },

    //重写显示随机符号
    ShowRandomSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbols.length)
        this._id = cfg.randomSymbols[randIdx-1]
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node){
            this._showNode = cc.find(cfg.symbol[this._id].node,this.node)
            this.playSymbolAni(1);
        }
        else{
            console.log("未找到配置id:" + this._id)
        }
    },

    //翻转符号(显示正面)
    reverseSymbol(id,data){
        this._id = id;
        this.playSymbolAni(3);
        if(this._id == 8){
            this.showKuang();
            this.scheduleOnce(()=>{
                this.showCoinNum(data.addcoin,data.addpool);
            },0.2)
        }else{
            this.showtype = 0;
        }
    },

    //显示金币 showtype 1显示金币 2显示jackpot
    showCoinNum(addnum,pool,playsound=true){
        if(addnum > 0){
            this.showtype = 1;
            this.totalCoin += addnum;
            this._jackpot.active = false;
            this._num.active = true;
            this._num.getComponent(cc.Label).string = Global.convertNumToShort(addnum,1000,0);
            this._num.scaleY = 0;
            cc.tween(this._num).to(0.2,{scaleY:1}).start();
        }else if(pool > 0){
            this.showtype = 2;
            this.pool = pool;
            this._num.active = false;
            this._jackpot.active = true;
            this.updateJackpotImg(this._jackpot,'symbol','theme132_s_'+(28+pool));
            this._jackpot.scaleY = 0;
            cc.tween(this._jackpot).to(0.2,{scaleY:1}).start();

        }else{
            if(playsound){
                if(cc.vv.gameData.isFreeGame()){
                    Global.playHSEffect('bonus_land_3');
                }
            }
        }
    },

    //播放动作s1/s2 type 1展示 2关闭 3打开
    playSymbolAni(type){
        if(this._showNode&&this._state!=type){
            this._showNode.active = true;
            let ske = this._showNode.getComponent(sp.Skeleton);
            let aniname = this._id==8?'animationj_'+type:'animation'+this._id+'_'+type;
            ske.setAnimation(0,aniname,false);
            this._state = type;
        }
    },

    //播放进入免费动画
    playScatterAnimation(isplay){
        if(this._id != 1){
            return
        }
        let cfg = cc.vv.gameData.getGameCfg();
        let wnode = cc.find(cfg.symbol[this._id].win_node,this.node);
        if(isplay){
            wnode.active = true;
            wnode.getComponent(sp.Skeleton).setAnimation(0,"animation",true);
        }else{
            wnode.active = false;
        }
    },
    
    //开始旋转隐藏符号/
    spineHideSymbol(){
        let bonusdata = cc.vv.gameData.GetBounusData();
        let selectdata = cc.vv.gameData.GetSelectData();
        if(bonusdata.state ||selectdata.state){
            cc.find('s1',this.node).active = false;
        }else{
            this.hideOtherNode();
        }
        this.playSymbolAni(2);
    },

    //隐藏当前动画节点
    hideOtherNode(){
        let children = this.node.children;
        for (let i = 0, count=children.length; i < count; i++) {
            if(children[i].name != 's1')
                children[i].active = false;
        }
        this.clearData();
    },

    //进入bonus游戏时 如果时金币播放框的光效/非金币设置灰度展示
    enterBonusGame(){
        if(this._id == 8){
            this._kuang.active = true;
        }
        this._showNode.active = false;
        this._showNode = cc.find(this._freeSymbolName,this.node)
        this.playSymbolAni(1);
    },

    //进收集游戏 背面改成红底
    enterCollectGame(){
        this._kuang.active = false;
        this.totalCoin = 0;
        this._showNode = cc.find(this._freeSymbolName,this.node)
        this._showNode.active = true;
    },

    //金币/jackpot开始移动
    moveCoinOrJackpot(){
        if(this.showtype == 1){
            this.moveCoinToBottom();
        }else if(this.showtype == 2){
            this.moveJackpotToTop();
        }
    },

    //移动获取的金币到底部
    moveCoinToBottom(){
        let instnode = cc.instantiate(this._num);
        instnode.parent = this.node;
        this._num.getComponent(cc.Label).string = '';
        let targetpos = this._bottom.position;
        cc.tween(instnode).to(0.3,{scale:0}).call(()=>{  
            cc.vv.gameData.playSpine(this._numscalesp,'animation',false,null); 
            Global.playHSEffect('bonus_collect');
            this.resetFrameColor(this._bottom);
            cc.tween(instnode).to(1,{scale:1},{easing:'backInOut'}).call(()=>{ 
                cc.vv.gameData.playSpine(this._nummovebtsp,'animation1',false,null); 
                cc.tween(instnode).to(1,{position:targetpos,scale:0},{easing:'backInOut'}).call(()=>{
                    instnode.destroy();
                   //底部显示coin数量/同时播放开始按钮spine
                   cc.find('totalnum',this._bottom).getComponent(cc.Label).string = Global.convertNumToShort(this.totalCoin,1000,0);
                }).start();
            }).start();
        }).start();
    },

    //移动获取jackpot到顶部
    moveJackpotToTop(){
        let instnode = cc.instantiate(this._jackpot);
        instnode.parent = this.node;
        this._jackpot.active = false;
        let targetpos = this._top.position;
        cc.tween(instnode).to(0.3,{scale:0}).call(()=>{  
            cc.vv.gameData.playSpine(this._numscalesp,'animation',false,null); 
            Global.playHSEffect('bonus_collect');
            this.resetFrameColor(this._top);
            cc.tween(instnode).to(1,{scale:1},{easing:'backInOut'}).call(()=>{
                cc.vv.gameData.playSpine(this._nummovebtsp,'animation2',false,null); 
                cc.tween(instnode).to(1,{position:targetpos,scale:0},{easing:'backInOut'}).call(()=>{
                    instnode.destroy();
                    //顶部显示jackpot图标
                    let jackimg = cc.find('jackpotimg',this._top);
                    jackimg.active = true;
                    this.updateJackpotImg(jackimg,'base','theme132_s_top'+(28+this.pool));
                }).start();
            }).start();
        }).start();
    },

    //改变jackpot图标
    updateJackpotImg(spimg,atlasname,spname){
        let atlas = cc.vv.gameData.GetAtlasByName(atlasname)
        spimg.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame(spname);
    },

    //金币出现加速光效显示
    coinSpeedLightShow(isshow){
        let lightnode = cc.find('speedlight',this.node);
        lightnode.active = isshow;
        if(isshow){
            cc.vv.gameData.playSpine(lightnode,'animation',false,null);
            Global.shakeNode(this.node,3,1,this.node.position);
            Global.playHSEffect('bonus_notify');
        }
    },

    //清空数据
    clearData(){
        cc.find('totalnum',this._bottom).getComponent(cc.Label).string = '';
        cc.find('jackpotimg',this._top).active = false;
    },

    //免费结束隐藏对象
    hideFreeObject(){
        this._bottom.active = false;
        this._top.active = false;
        this._num.active = true;
        if(this._showNode.name != 's1'){
            this._showNode.active = false;
            this._showNode = cc.find('s1',this.node);
            this.playSymbolAni(1);
        }
    },

    //显示边框
    showKuang(){
        let bonusdata = cc.vv.gameData.GetBounusData();
        if(!this._kuang.active&&bonusdata.state){
            this._kuang.active = true;
            this._kuangguang.active = true;
            cc.vv.gameData.playSpine(this._kuangguang,'animation1',true,null);
        }
    },

    //新增奖金图标播放光效
    newCoinShowKuang(){
        if(!this._kuangguang.active)
            return;
        cc.vv.gameData.playSpine(this._kuangguang,'animation2',false,()=>{
            this._kuangguang.active = false;
        })
    },

    ////////////免费结束复位显示card
    resetEnterFreeSymbol(id,data){
        cc.find('s2',this.node).active = false;
        this._id = id;
        this._showNode = cc.find('s1',this.node)
        this.playSymbolAni(1);
        this._bottom.active = false;
        this._top.active = false;
        this.showCoinNum(data.coin,data.pool,false);
        this.totalCoin = 0;
        this._kuang.active = false;
    },

    //显示时复原框颜色
    resetFrameColor(bgnode){
        bgnode.active = true;
        bgnode.color = cc.color(255,255,255);
    },
});
