
cc.Class({
    extends: cc.Component,

    properties: {
        _nextStep:cc.callFunc,
        _maxBetEnterBonus:13,               //最大押注索引改变进入bonus游戏收集数
        _isReConnect:false,
    },
    onLoad () {
        this._startSpine = cc.find('safe_node/screenspine/startfree',this.node);
        this._pressStartSpine = cc.find('safe_node/freeui/pressstart/sp',this.node);
        this._collectSpine = cc.find('safe_node/freeui/collectsp',this.node);
        this._collectResultSp = cc.find('safe_node/freeui/collectresultsp',this.node);

        //press start按钮事件
        this._pressNode = cc.find('safe_node/freeui/pressstart',this.node)
        this._pressNode.on(cc.Node.EventType.TOUCH_END, this.onPressStart,this);
        
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onChangeBetValue,this)
    },

    onEnable(){
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this); 
    },

    //断线重连没有点击开始
    reConnectShowPressStart(delay=1){
        this._isReConnect = delay == 1?true:false;
        this.scheduleOnce(()=>{
            this._pressNode.active = true;
            this._pressStartSpine.scale = 1;
            Global.playHSEffect('bonus_start');
            this.showFreeGameUI(true);
            cc.vv.gameData.playSpine(this._pressStartSpine,'animation1',false,()=>{
                this._pressShow = true;
                cc.vv.gameData.playSpine(this._pressStartSpine,'animation2',true,null);
            });

            cc.vv.gameData.checkAutoPlay(this._pressNode, ()=>{
                if(!this._pressShow)
                    return;
                this._pressShow = false;
                Global.playHSEffect('button_start');
                cc.tween(this._pressStartSpine).to(0.5,{scale:0},{easing:'backInOut'}).call(()=>{
                    this._pressNode.active = false;
                    this.scheduleOnce(() => {
                        this.sendEnterFreeeGame();
                        //继续流程(开始免费游戏)
                        //  if(this._nextStep){
                        //     this._nextStep();
                        // }
                    }, 0.5);
                }).start();
            });
        },delay)
    },

    //触发免费游戏 isCollectGame:是否是收集游戏
    async enterFreeGame(symbols, isCollectGame){
        return new Promise((success)=>{
            this._nextStep = success;
            this._symbolScript = symbols;
            let select = cc.vv.gameData.GetSelectData();
            if(select.state|| isCollectGame){
                //进入免费游戏
                console.log("#####进入免费");
                this.playEnterFreeAni(()=>{
                    this.updateFreeGame(true);
                });
                this.scheduleOnce(()=>{
                    this.showFreeGameUI(true);
                    if(this._symbolScript){
                        this._symbolScript.forEach(syb => {
                            syb.enterBonusGame();
                        });
                    }
                },0.3);
            }else{
                let bonusdata = cc.vv.gameData.GetBounusData();
                if(bonusdata.state){
                    //播放金币移动动画
                    let isadd = this.isAddCoin(bonusdata.data);
                    this.updateFreeGame(false,isadd);
                }else{
                    success();
                }
            }
        })
    },

    //判断是否新增coin/pool
    isAddCoin(data){
        for(let key in data){
            if(data[key].addpool>0||data[key].addcoin>0){
                return true;
            }
        }
        return false;
    },

    //开始进入bonus游戏播放效果/展示按钮特效
    updateFreeGame(istigger,isadd){
        //触发bonus游戏时 展示对应效果 
        this.scheduleOnce(()=>{
            if(this._symbolScript){
                this._symbolScript.forEach(syb => {
                    syb.moveCoinOrJackpot();
                });
            }
        },0.5);
        if(istigger){
            this.reConnectShowPressStart(3);
        }else{
            let delay = isadd?3:0.5;
            this.scheduleOnce(()=>{
                if(this._nextStep){
                    this._nextStep();
                    this._nextStep = null

                }
            },delay);
        }
     },

    //免费游戏结束处理
    freeGameOver(symbols){
        //隐藏旋转次数
        let timesnode = cc.find("safe_node/slots/descui/freetimes",this.node);
        cc.tween(timesnode).to(1,{opacity:0}).call(()=>{
            timesnode.active = false;
            timesnode.opacity = 255;
            cc.find("Canvas/safe_node/LMSlots_Collect_Puzzle").active = true;
        }).start();

        //开始收集金币
        this.playCollectCoin(symbols);
        
    },

    //播放进入免费动画
    playEnterFreeAni(callback){
        Global.playHSEffect('bonus_transiton');
        cc.vv.gameData.playSpine(this._startSpine,'animation',false,()=>{
            if(callback){
                callback();
            }
        });
    },

    // //press start点击事件
    onPressStart(){
        if(!this._pressShow)
            return;
        this._pressShow = false;
        this._pressNode.stopAllActions();
        Global.playHSEffect('button_start');
        cc.tween(this._pressStartSpine).to(0.5,{scale:0},{easing:'backInOut'}).call(()=>{
            this._pressNode.active = false;         
            this.scheduleOnce(() => {
                this.sendEnterFreeeGame();
                 //继续流程(开始免费游戏)
                //  if(this._nextStep){
                //     this._nextStep();
                // }
            }, 0.5);
        }).start();
    },

    //显示免费界面
    showFreeGameUI(isshow,count = 3){
        if(isshow){
            Global.SlotsSoundMgr.playBgm('bonus_bgm')
        }else{
            Global.SlotsSoundMgr.stopBgm();
        }
        this.changeBg(isshow);
        cc.find("safe_node/slots/descui/desc1",this.node).active = !isshow;
        cc.find("safe_node/slots/descui/freetimes",this.node).active = isshow;
        this.updateFreetimes(count,true);
    },

    //更新免费次数
    updateFreetimes(count,isinit=false){
        let atlas = cc.vv.gameData.GetAtlasByName("base")
        let spr = cc.find("safe_node/slots/descui/freetimes/freecount",this.node);
        spr.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme132_cnt"+count);
        if(count == 3&&!isinit){
            let respin = cc.find("safe_node/slots/descui/freetimes/respin",this.node);
            respin.active = true;
            cc.vv.gameData.playSpine(respin,'animation',false,null);
        }
    },

    //开始播放收集动画
    playCollectCoin(symbols){
        this._collectSpine.active = true;
        let index = 0;
        let curtotal = 0;
        let safenode = cc.find('safe_node',this.node);
        let winnode = cc.vv.gameData.GetBottomScript().getWinLabelNor();//cc.find('safe_node/LMSlots_Bottom/winBg/lbl_winNum_nor',this.node);
        this._collectResultSp.position = safenode.convertToNodeSpaceAR(winnode.convertToWorldSpaceAR(cc.v2(0,0)))

        let self = this;
        let flyAnimation = function(){       
            if(index >= symbols.length){
                console.log("###退出收集");
                self.scheduleOnce(() => {
                    self.playEnterFreeAni(()=>{
                        cc.vv.gameData.GetBottomScript().SetWin(0);
                        self.collectOverHandle();
                    });
                    self.scheduleOnce(() => {
                        cc.vv.gameData.GetSlotsScript().resetEnterFreeCards();
                        self.showFreeGameUI(false);
                    }, 0.5);
                }, 1);
                return;
            }
            let symboldata = self.getBonusDataByindex(index+1);
            if(symboldata){
                let symbolnode = symbols[index].node;
                if(symboldata.pool > 0){
                    if(cc.find('topbag',symbolnode).active){
                        let tobgnode = cc.find('topbag/spine',symbolnode);
                        cc.vv.gameData.playSpine(tobgnode,'animation',false,null); 
                        let jackpotcoin = cc.vv.gameData.getPoolbyType(symboldata.pool);
                        curtotal += jackpotcoin;
                        //延时显示jackpot界面 中奖数还不知道怎么获取
                        self.scheduleOnce(() => { 
                            //已收集修改框颜色为蓝色
                            self.collectChangeFrameColor(cc.find('topbag',symbolnode));
                            self.showJackpotCollectUI(symboldata.pool,jackpotcoin);
                        }, 0.5); 
                        self.scheduleOnce(() => {
                            cc.vv.gameData.GetBottomScript().SetWin(curtotal);
                            cc.vv.gameData.clearBonusDataPool(index+1);
                            flyAnimation();
                        }, 6); 
                    }else{
                        flyAnimation()
                    }
                    
                }else if(symboldata.coin > 0){
                    if(cc.find('bottombg',symbolnode).active){
                        let bbgnode = cc.find('bottombg/spine',symbolnode);
                        cc.vv.gameData.playSpine(bbgnode,'animation',false,null); 
                        let startpos = safenode.convertToNodeSpaceAR(bbgnode.convertToWorldSpaceAR(cc.v2(0,0)))
                        let endpos = safenode.convertToNodeSpaceAR(winnode.convertToWorldSpaceAR(cc.v2(0,0)))
                        self._collectSpine.getComponent(sp.Skeleton).setAnimation(0,'animation',false);

                        //设置缩放和角度
                        let v = cc.v2(endpos.x, endpos.y).sub(cc.v2(startpos.x, startpos.y));
                        let length = v.mag();
                        self._collectSpine.scale = length/460;
                        let angle = v.signAngle(cc.v2(1, 0));
                        self._collectSpine.angle = -angle * cc.macro.DEG + 90;
                        self._collectSpine.position = startpos;

                        curtotal +=  symboldata.coin;
                        Global.playHSEffect('bonus_hit');
                        //已收集修改框颜色为蓝色
                        self.collectChangeFrameColor(cc.find('bottombg',symbolnode));
                        self.scheduleOnce(() => {
                            self._collectResultSp.active = true;
                            self._collectResultSp.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                            //同时显示获取金币数
                            cc.vv.gameData.GetBottomScript().SetWin(curtotal);
                        }, 0.5); //5秒
                    }

                    index++;
                    self.scheduleOnce(() => {
                        flyAnimation();
                    }, 1);
                }else{
                    index++;
                    flyAnimation();
                }
            }else{
                index++;
                flyAnimation();
            }
        }
        flyAnimation();
    },

    //显示jackpot界面
    showJackpotCollectUI(pool,jackpotcoin){
        let jackpotui = cc.find('safe_node/freeui/jackpotui',this.node);
        let mainnode = cc.find('mainnode',jackpotui);
        let framenode = cc.find('framebg',mainnode);
        let descnode = cc.find('bottomdesc',mainnode);
        //改变头颜色
        let headnode ;
        for(let i=1;i<5;i++){
            if(pool == i){
                headnode = cc.find("head"+i,mainnode);
                headnode.active = true;
            }else{
                cc.find("head"+i,mainnode).active = false;
            }
        }
        //改变界面背景
        let atlas = cc.vv.gameData.GetAtlasByName("dialog1")
        let spr = cc.find("bg",mainnode);
        let spname = this.getJackputUIBgSpritename(pool);
        spr.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame(spname);

        //显示界面/显示获取金币
        jackpotui.active = true;
        //界面动态效果
        mainnode.scale = 0;
        descnode.scale = 0;
        headnode.scale = 0;
        framenode.scale = 0;
        Global.playHSEffect('bonus_collect');
        
        cc.tween(mainnode).to(0.4,{scale:1},{easing:'backInOut'}).call(()=>{ 
            cc.tween(headnode).to(0.3,{scale:1},{easing:'backInOut'}).start(); 
            cc.tween(framenode).to(0.6,{scale:1},{easing:'backInOut'}).call(()=>{
                let lblcoin = cc.find('mainnode/framebg/totalnum',jackpotui);
                Global.doRoallNumEff(lblcoin,0,jackpotcoin,1,()=>{
                    Global.playHSEffect('bonus_end');
                },null,0,true);
            }).start(); 
            cc.tween(descnode).to(0.3,{scale:1},{easing:'backInOut'}).start(); 
        }).start();

        //1.5秒后自动隐藏
        this.scheduleOnce(()=>{
            cc.tween(mainnode).to(0.5,{scale:0}).call(()=>{
                jackpotui.active = false;
            }).start();
        },5)
    },

    //获取jackpot界面背景spritename
    getJackputUIBgSpritename(pool){
        switch (pool) {
            case 1:return 'theme132_dialog_bg4';
            case 2:return 'theme132_dialog_bg3';
            case 3:return 'theme132_dialog_bg4';
            case 4:return 'theme132_dialog_bg1';
        }
    },

    //收集后改变框颜色
    collectChangeFrameColor(bgnode){
        //蓝色
        bgnode.color = cc.color(64,91,255);
    },

    //收集结束处理
    collectOverHandle(){
        cc.vv.gameData.GetSlotsScript().freeOverHideObj();
        //cc.find('safe_node/slots',this.node).getComponent("ThePanda_Slots").freeOverHideObj();
        cc.vv.gameData.clearBonusState();
    },

    //按符号位置获取bonus数据
    getBonusDataByindex(index){
        let bonusdata = cc.vv.gameData.GetBounusData().data;
        for(let key in bonusdata){
            if(bonusdata[key].idx == index){
                return bonusdata[key];
            }
        }
        return null;
    },

    //获取旋转角度
    getRotationAngle(pos){
        switch (pos) {
            case 1:return -12;
            case 7:return -18;
            case 13:return -35;
            case 2:return -2;
            case 8:return -2;
            case 14:return -3;
            case 3:return -20;
            case 4:return -10;
            case 10:return -35;
            case 5:return 5;
            case 12:return 10;
            case 6:return -33;
            case 9:return 15;
            case 11:return -15;
        }
        return 0;
    },



    changeLightAngleAndScale(startNode, endNode, signAngleStandard, dir, offsetAngle, size) {
        let endPos = endNode.convertToWorldSpaceAR(cc.v2(0, 0));
        let startPos = startNode.convertToWorldSpaceAR(cc.v2(0, 0));
        let dx = endPos.x - startPos.x;
        let dy = endPos.y - startPos.y;
        let dPos = cc.v2(dx, dy);
        let angle = dPos.signAngle(cc.v2(0, 1));
        let degree = angle / Math.PI * 180;
        startNode.angle = degree * dir + offsetAngle;
        let dis = Math.abs(dPos.mag());
        startNode.scale = dis / size;
    },

    //获取缩放比例
    getScaleMul(from, to){
        //设置缩放和角度
        let v = cc.v2(to.x, to.y).sub(cc.v2(from.x, from.y));
        let length = v.mag();
        this._flash.scale = length/220;
        let angle = v.signAngle(cc.v2(1, 0));
        this._flash.angle = -angle * cc.macro.DEG - 90;
        this._flash.position = from;



        switch (pos) {
            case 1:
            case 2:return 1.5;
            case 3:
            case 4:
            case 5:return 1.3;
            case 6:
            case 7:
            case 8:
            case 9:return 1.1;
            case 10:
            case 11:
            case 12:return 0.75;
            case 13:
            case 14:return 0.45;
        }
        return 1;
    },

     //押注额改变val
     onChangeBetValue(data){
        let descnode = cc.find("safe_node/slots/descui/desc1",this.node);
        if(!descnode.active)
            return;
        let changespine = cc.find("safe_node/slots/descui/desc1/changespine",this.node)
        let betIdx = cc.vv.gameData.GetBetIdx();
        let atlas = cc.vv.gameData.GetAtlasByName("base")
        let spr = cc.find('num',descnode);
        if(betIdx < this._maxBetEnterBonus){
            //6个
            if(cc.vv.gameData.getNeedBonusIconNum() != 6){
                Global.playHSEffect('board_change');
                cc.vv.gameData.playSpine(changespine,'animation',false,null);
                cc.vv.gameData.setBonusIconNum(6);
                spr.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme132_tip2");
            }
        }else{
            if(cc.vv.gameData.getNeedBonusIconNum() != 5){
                Global.playHSEffect('board_change');
                cc.vv.gameData.playSpine(changespine,'animation',false,null);
                cc.vv.gameData.setBonusIconNum(5);
                spr.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme132_tip1");
            }
        }
    },

    //改变背景
    changeBg(isfree){
        let bgCmp = cc.find('safe_node/bg',this.node).getComponent("ImgSwitchCmp");

        if(isfree){
            bgCmp.setIndex(1);
        }else{
            bgCmp.setIndex(0);
        }
    },

     //发送进入免费游戏
     sendEnterFreeeGame(){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.data = {}
        req.data.rtype = 1
        req.gameid = cc.vv.gameData.getGameId()
        cc.vv.NetManager.send(req,true);
    },

    onRcvSubGameAction:function(msg){
        if(msg.code == 200 ){
            if(msg.data.rtype == 20){
                //收集碎片
            }else if(msg.data.rtype == 1) {
                // console.log("---1cc.vv.gameData.GetCollectGame()",cc.vv.gameData.GetCollectGame())
                if(cc.vv.gameData.GetCollectGame() && msg.data.chipGame == null){
                    //进收集游戏的bonus游戏
                    // console.log("---1fasong444444444441111111");
                    cc.vv.gameData.GetBottomScript().SendSpinReq();
                    cc.vv.gameData.SetCollectGame(false)
                    return
                }
                let selectdata = cc.vv.gameData.GetSelectData();
                if(this._isReConnect&&selectdata.state){
                    // console.log("---1自动旋转autoStartSpin");
                    cc.vv.gameData.GetSlotsScript().autoStartSpin();
                    //cc.find('safe_node/slots',this.node).getComponent("ThePanda_Slots").autoStartSpin();
                    this._isReConnect = false;
                }else{
                    if(this._nextStep){
                        this._nextStep();
                        this._nextStep = null
                    }
                }
            }

        }
    }
});
