

cc.Class({
    extends: require('LMSlots_Slots_Base'),

    properties: {
        //_firstInit:true,
        _symbolCount:14,
        _symbols:[],   //符号对象
        _stopAutoShowSymbol:false,
        _enterCards:[],
        _reverseSpeed:0.2,
    },
    //重写初始化符号
    Init:function(){
        let self = this
        this._enterCards=[3,2,3,4,5,6,7,2,3,4,7,2,4,7];
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()

        this._cfg = cc.vv.gameData.getGameCfg()
        this.createSymbol()
        this._bottomScript.ShowBtnsByState("idle")
        this.RegisterEvent()
        //断线重连的显示
        this.ReconnectShow()
        this.node.parent.parent.getComponent("LMSlots_Puzzle").setCallback((freeInfo, chipGame)=>{
           // 进入免费的逻辑
           console.log("---1收集游戏的callback逻辑")
            //保存进入时的cards
            // if(chipGame.cards){
            //     this._enterCards = chipGame.cards;
            // }else{
            // }
            if(this._gameInfo){
                this._enterCards = this._gameInfo.resultCards;
                this._enterBonusData = this._gameInfo.bonusData;
            }else{
                this._enterCards = [];
                this._enterBonusData = cc.vv.gameData.GetBounusData();
            }
            this._enterBonusData.data = []

           cc.vv.gameData.SetCollectGame(true)
           cc.vv.gameData.GetFreeGameScript().enterFreeGame(null, true);
            for(let i=0;i<this._symbols.length;i++){
                this._symbols[i].enterCollectGame()
            }
           this.hideSymbols();
        });
    },
    //重写重连显示
    ReconnectShow:function(){
        //是否进入免费判断
        let selectdata = cc.vv.gameData.GetSelectData();
        let bonusdata = cc.vv.gameData.GetBounusData();
        if(selectdata.state||bonusdata.state){
            //免费游戏中
            for(let i=0;i<this._symbols.length;i++){
                let data = this.GetCoinData(i+1);
                this._symbols[i].initShowSymbol(bonusdata.cards[i],data.pool,data.coin,selectdata.state);
            }
            if(selectdata.state){
                //需要点击开始
                cc.vv.gameData.GetFreeGameScript().reConnectShowPressStart();
            }else{
                cc.vv.gameData.GetFreeGameScript().showFreeGameUI(true,bonusdata.num);
                this.autoStartSpin();
            }
        }
    },

    //自动开始旋转
    autoStartSpin(){
        this.scheduleOnce(()=>{
            this.hideSymbols();
        },0.5)
        this.scheduleOnce(()=>{
            //下一局
            this.CanDoNextRound();
        },1)
    },

    //重写
    StartMove:function(){
        this._super();
        Global.SlotsSoundMgr.playNormalBgm();
    },

    //重写收到服务器消息处理
    async onMsgSpine(msg){
        this._gameInfo = msg
        if(msg.select&&msg.select.state){
            //保存进入时的cards
            this._enterCards = msg.resultCards;
            this._enterBonusData = msg.bonusData;
        }
        // this.scheduleOnce(async ()=> {
            
        // })
        this._stopAutoShowSymbol = false;
        await this.startReverseCards(this._gameInfo.bonusData);
        this._stopTime = -1;
        //显示中奖路线
        let bonusdata = cc.vv.gameData.GetBounusData();
        let selectdata = cc.vv.gameData.GetSelectData();
        if(selectdata.state){
            Global.playHSEffect('bell');
        }
        if(!bonusdata.state&&!selectdata.state){
            this.ShowWinTrace()
            //显示底部赢钱
            await this.playBottomWin();
        }
        await cc.vv.gameData.GetFreeGameScript().enterFreeGame(this._symbols);
        await this.spineOver();
        //下一局
        this.CanDoNextRound();
    },

    //spin结束 自动反转到盖牌状态/模拟点击效果
    async spineOver(){
        return new Promise((success)=>{
            this._nextStep = success;
            let bonusdata = cc.vv.gameData.GetBounusData();
            if(bonusdata&&bonusdata.state){
                console.log("####旋转结束:"+bonusdata.num);
                if(bonusdata.num > 0){
                    this.onSpin();
                    this.scheduleOnce(()=>{
                        success()
                    },1);
                }else{
                    //显示结束提示
                    cc.vv.gameData.GetFreeGameScript().freeGameOver(this._symbols);
                }    
            }else{
                let selectdata = cc.vv.gameData.GetSelectData();
                if(selectdata.state){
                    this.onSpin();
                }
                this.scheduleOnce(()=>{
                    success()
                },0.5);
            }
        });
    },

    async playBottomWin () {
        return new Promise((success)=>{
            let nWin = cc.vv.gameData.GetGameWin()
            let nTotal = nWin
            let updateAllCoin = true;
            let bonusdata = cc.vv.gameData.GetBounusData();
            let selectdata = cc.vv.gameData.GetSelectData();
            if(selectdata.state||bonusdata.state){
                nTotal = bonusdata.coin;
                updateAllCoin = true;
            }

            this.ShowBottomWin(nWin,nTotal,updateAllCoin,()=>{
                success();
            });


        });
    },

    //重写点击停止
    async StopMove(){
        this._super();
        console.log("###点击停止移动");
        //直接显示结果
        this._stopAutoShowSymbol = true;
    },

    //点击spin
    onSpin(){
        //隐藏动画/盖住所有牌
        this.hideSymbols();
    },

    //盖上符号
    hideSymbols(){
        Global.playHSEffect('reel_change');
        for(let i=0;i<this._symbols.length;i++){
            this._symbols[i].spineHideSymbol();
        }
        //隐藏中奖框
        let bonusdata = cc.vv.gameData.GetBounusData();
        if(!bonusdata.state){
            this.hideAllWinningBox();
            let select = cc.vv.gameData.GetSelectData();
            if(select&&select.state){
                //免费第一次旋转时select 为true bonusdata state为false
                cc.vv.gameData.GetFreeGameScript().updateFreetimes(2);
            }
        }else{
            //改变免费次数
            cc.vv.gameData.GetFreeGameScript().updateFreetimes(bonusdata.num-1);
        }
    },

    //正常翻转动画
    async startReverseCards(bonusdata){
        // await this.awaitTime(0.3);
        await this.startShowCards();
        //更新免费次数
        if(bonusdata.state){
            this.showNewCoinKuangGuang();
            cc.vv.gameData.GetFreeGameScript().updateFreetimes(bonusdata.num);
        }
        if(bonusdata.state&&bonusdata.num == 0){
            Global.playHSEffect('bouns_play_end');
        }
        await this.awaitTime(0.5);
        
    },

    //新翻出的奖金图标 显示光效
    showNewCoinKuangGuang(){
        for(let i=0;i<this._symbols.length;i++){
            this._symbols[i].newCoinShowKuang();
        }
    },

    //开始显示符号
    async startShowCards(){
        return new Promise((success)=>{
            let cards = this._gameInfo.resultCards;
            let index = 0;
            let self = this;
            let coincount = 0;
            this._reverseSpeed = 0.2;
            //直接显示card
            let showcards = function(){
                for(let i=0;i<self._symbols.length;i++){
                    self.showSymbols(self._symbols[i],cards[i],i+1);
                    self._symbols[i].coinSpeedLightShow(false);
                }
            }
            let bonusnum = cc.vv.gameData.getNeedBonusIconNum()-1;
            //自动显示card
            let autoshowcards = function(){
                if(self._symbols[index]){
                    if(cards[index] == 8){
                        coincount++;
                        if(coincount >= bonusnum){
                            Global.playHSEffect('bonus_land_3');
                        }else{
                            if(cc.vv.gameData.isFreeGame()){
                                Global.playHSEffect('bonus_land_2');
                            }else{
                                Global.playHSEffect('bonus_land_1');
                            }
                        }
                    }else{
                        Global.playHSEffect('reel_stop');
                    }
                    let bonusdata = cc.vv.gameData.GetBounusData();
                    if(coincount >= bonusnum&&!bonusdata.state){
                        self._reverseSpeed = 1.2;
                        //下一个翻开的显示光效
                        if(self._symbols.length > index+1){
                            self._symbols[index+1].coinSpeedLightShow(true);
                        }
                    }
                    self._symbols[index].coinSpeedLightShow(false);
                    self.showSymbols(self._symbols[index],cards[index],index+1);
                    index++;
                    self.scheduleOnce(() => {
                        if(self._stopAutoShowSymbol){
                            showcards();
                            success();
                        }else{
                            autoshowcards();
                        }
                    }, self._reverseSpeed);
                }else{
                    success();
                }  
            }  
            autoshowcards();  
        })
    },

    //符号显示正面 
    showSymbols(symscript,id,index){
        let data = this.GetCoinData(index);
        symscript.reverseSymbol(id,data);
    },

    //获取到的coin数值 index从1开始
    GetCoinData(index){
        let bonusdata = cc.vv.gameData.GetBounusData().data;
        if(bonusdata){
            for(let key in bonusdata){
                if(bonusdata[key].idx == index){
                    return bonusdata[key];
                }
            }
        }
        return 0;
    },


    //显示
    //随机创建符号
    createSymbol(){
        let symbol = this._cfg.scripts.Symbols
        for (let idx = 0; idx < this._symbolCount; idx++) {
            let node = cc.find("reels/Panda_Symbol" + (idx+1),this.node)
            let scp = node.addComponent(symbol)
            scp.Init(idx)
            this._symbols.push(scp)
        }
    },
    
    //重写显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace:function(){
        let allWinIdx = []

        //中奖位置
        for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
            let item = this._gameInfo.zjLuXian[i]
            for(let idx = 0; idx < item.indexs.length; idx++){
                allWinIdx[item.indexs[idx]] = 1
            }
        }
        if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
            for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                let val = this._gameInfo.scatterZJLuXian.indexs[i]
                allWinIdx[val] = 1
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){

                symbol.playWinAnimation()
            }
        }
        
        this.showWinningBox(allWinIdx);
    },

    //显示中奖边框
    showWinningBox(allwinidx){
        let boxcfg = cc.vv.gameData.getGameCfg().winningBox;
        let winbox = {};
        //线获取中线位置包含的外框
        for(let idx in allwinidx){
            let box = boxcfg[idx-1];
            box.forEach(name => {
                if(winbox[name]){
                    winbox[name] += 1;
                }else{
                    winbox[name] = 1;
                }
            });
        }
        //显示外框
        let framenode = cc.find('node_frame',this.node);
        for(let key in winbox){
            if(winbox[key] == 1){
                framenode.getChildByName(key).active = true;
            }
        }
    },

    //隐藏所有中奖边框
    hideAllWinningBox(){
        let framenode = cc.find('node_frame',this.node);
        let children = framenode.children;
        for (let i = 0, count=children.length; i < count; i++) {
            children[i].active = false;
        }
    },

    //免费结束隐藏对应对象
    async freeOverHideObj(){
        this.hideAllWinningBox();
        await this.playBottomWin();
        if(this._nextStep){
            this._nextStep();
        }
    },

    //重写通过位置获取符号
    GetSymbolByIdx(idx){
        return this._symbols[idx-1];
    },

     //////////////////恢复进入免费时的card状态/////////////////////////////
     resetEnterFreeCards(){
        for(let i=0;i<this._symbols.length;i++){
            let data = this.GetEnterBonusData(i+1);
            this._symbols[i].resetEnterFreeSymbol(this._enterCards[i],data);
        }
     },

    //获取到的coin数值 index从1开始
    GetEnterBonusData(index){
        if(this._enterBonusData&&this._enterBonusData.data){
            let data = this._enterBonusData.data;
            for(let key in data){
                if(data[key].idx == index){
                    return data[key];
                }
            }
        }
        return 0;
    },
    ////////////////////////恢复进入免费时的card状态 END///////////////////////

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
